from pathlib import Path

path = Path('/home/ubuntu/mineirada-replica/client/src/App.tsx')
text = path.read_text()

text = text.replace('type RecordItem = Record<string, string | number>;', '''type RecordItem = Record<string, string | number>;
type ProductionOrder = { number: string; product: string; quantity: string; delivery: string; priority: string; status: string; notes: string };
type StockMovement = { id: string; type: string; item: string; quantity: string; unit: string; origin: string; destination: string; date: string; note: string };
type QualityRecord = { id: string; category: "Checklist" | "Não conformidade"; subject: string; status: string; responsible: string; date: string; notes: string };
type MaintenanceOrder = { id: string; asset: string; type: string; priority: string; status: string; date: string; description: string };
type AuditEvent = { id: string; module: string; action: string; user: string; date: string; detail: string };''', 1)

text = text.replace('''  lots: [] as Array<{ lot: string; material: string; total: string; remaining: string; expiry: string; location: string; status: string }>,''', '''  lots: [] as Array<{ lot: string; material: string; total: string; remaining: string; expiry: string; location: string; status: string }>,
  productionOrders: [] as ProductionOrder[], movements: [] as StockMovement[], qualityRecords: [] as QualityRecord[], maintenanceOrders: [] as MaintenanceOrder[], auditEvents: [] as AuditEvent[],''', 1)

modules = r'''
function auditEvent(module: string, action: string, detail: string): AuditEvent {
  let user = "Usuário"; try { const stored = JSON.parse(localStorage.getItem("mineirada_user_profile") || "null"); user = stored?.username || user; } catch { /* usar usuário padrão de validação */ }
  return { id: `AUD-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`, module, action, user, date: new Date().toLocaleString("pt-BR"), detail };
}

function ProductionOrdersPage({ data, setData }: { data: typeof initialData; setData: (value: typeof initialData) => void }) {
  const [query, setQuery] = useState(""); const [status, setStatus] = useState("Todos"); const [modal, setModal] = useState(false); const [editing, setEditing] = useState<number | null>(null); const [form, setForm] = useState<ProductionOrder>({ number: "", product: "", quantity: "", delivery: "", priority: "Normal", status: "Planejada", notes: "" }); const { showToast } = useToast();
  const rows = useMemo(() => data.productionOrders.filter((o) => `${o.number} ${o.product} ${o.status}`.toLowerCase().includes(query.toLowerCase()) && (status === "Todos" || o.status === status)), [data.productionOrders, query, status]);
  const openCreate = () => { setEditing(null); setForm({ number: `OP-${Date.now()}`, product: "", quantity: "", delivery: "", priority: "Normal", status: "Planejada", notes: "" }); setModal(true); };
  const openEdit = (index: number) => { const target = rows[index]; const realIndex = data.productionOrders.indexOf(target); if (realIndex < 0) return; setEditing(realIndex); setForm({ ...target }); setModal(true); };
  const save = (e: FormEvent) => { e.preventDefault(); if (!form.number.trim() || !form.product.trim() || !form.quantity.trim()) { showToast("Preencha número, produto e quantidade da ordem."); return; } const next = [...data.productionOrders]; const isNew = editing === null; if (isNew) next.unshift(form); else next[editing] = form; setData({ ...data, productionOrders: next, auditEvents: [auditEvent("Ordens de Produção", isNew ? "Criação" : "Atualização", `${form.number} · ${form.product}`), ...data.auditEvents] }); setModal(false); showToast(isNew ? "Ordem de produção criada." : "Ordem de produção atualizada."); };
  const remove = (index: number) => { const target = rows[index]; if (!target || !window.confirm(`Excluir a ordem ${target.number}?`)) return; setData({ ...data, productionOrders: data.productionOrders.filter((o) => o !== target), auditEvents: [auditEvent("Ordens de Produção", "Exclusão", target.number), ...data.auditEvents] }); showToast("Ordem removida."); };
  return <div className="page-content"><PageHeader title="Ordens de Produção" description="Planeje, acompanhe e atualize as ordens da fábrica"><Button icon={Plus} onClick={openCreate}>Nova OP</Button></PageHeader><div className="toolbar"><div className="search-box"><Search size={16} /><input placeholder="Buscar por OP ou produto..." value={query} onChange={(e) => setQuery(e.target.value)} /></div><SelectInput value={status} onChange={setStatus}><option>Todos</option><option>Planejada</option><option>Em produção</option><option>Concluída</option><option>Pausada</option><option>Cancelada</option></SelectInput><span className="record-count">{rows.length} ordens</span></div><div className="panel table-panel"><Table columns={["OP", "Produto", "Quantidade", "Entrega", "Prioridade", "Status"]} rows={rows.map((o) => [<span className="mono">{o.number}</span>, o.product, o.quantity, o.delivery || "—", <Pill tone={o.priority === "Urgente" ? "danger" : o.priority === "Alta" ? "warning" : "neutral"}>{o.priority}</Pill>, <Pill tone={o.status === "Concluída" ? "success" : o.status === "Em produção" ? "info" : o.status === "Cancelada" ? "danger" : "neutral"}>{o.status}</Pill>])} onEdit={openEdit} onDelete={remove} empty="Nenhuma ordem de produção cadastrada." /></div>{modal && <Modal title={`${editing === null ? "Nova" : "Editar"} Ordem de Produção`} onClose={() => setModal(false)} wide><form className="modal-form" onSubmit={save}><div className="form-grid"><Field label="Número da OP *"><TextInput value={form.number} onChange={(v) => setForm({ ...form, number: v })} /></Field><Field label="Produto *"><TextInput value={form.product} onChange={(v) => setForm({ ...form, product: v })} placeholder="Produto cadastrado" /></Field><Field label="Quantidade *"><TextInput value={form.quantity} onChange={(v) => setForm({ ...form, quantity: v })} type="number" placeholder="0" /></Field><Field label="Entrega"><TextInput value={form.delivery} onChange={(v) => setForm({ ...form, delivery: v })} type="date" /></Field><Field label="Prioridade"><SelectInput value={form.priority} onChange={(v) => setForm({ ...form, priority: v })}><option>Baixa</option><option>Normal</option><option>Alta</option><option>Urgente</option></SelectInput></Field><Field label="Status"><SelectInput value={form.status} onChange={(v) => setForm({ ...form, status: v })}><option>Planejada</option><option>Em produção</option><option>Concluída</option><option>Pausada</option><option>Cancelada</option></SelectInput></Field></div><Field label="Observações"><textarea className="input textarea" value={form.notes} onChange={(e) => setForm({ ...form, notes: e.target.value })} /></Field><div className="modal-actions"><Button variant="outline" onClick={() => setModal(false)}>Cancelar</Button><Button type="submit" icon={Check}>Salvar OP</Button></div></form></Modal>}</div>;
}

function MovementsPage({ data, setData }: { data: typeof initialData; setData: (value: typeof initialData) => void }) {
  const [modal, setModal] = useState(false); const [query, setQuery] = useState(""); const [form, setForm] = useState<StockMovement>({ id: "", type: "Entrada", item: "", quantity: "", unit: "", origin: "", destination: "", date: "", note: "" }); const { showToast } = useToast(); const rows = useMemo(() => data.movements.filter((m) => Object.values(m).join(" ").toLowerCase().includes(query.toLowerCase())), [data.movements, query]);
  const save = (e: FormEvent) => { e.preventDefault(); if (!form.item.trim() || !form.quantity.trim()) { showToast("Informe o item e a quantidade da movimentação."); return; } const next = { ...form, id: `MOV-${Date.now()}`, date: form.date || new Date().toISOString().slice(0, 10) }; setData({ ...data, movements: [next, ...data.movements], auditEvents: [auditEvent("Movimentações", "Criação", `${next.type} · ${next.item}`), ...data.auditEvents] }); setModal(false); setForm({ id: "", type: "Entrada", item: "", quantity: "", unit: "", origin: "", destination: "", date: "", note: "" }); showToast("Movimentação registrada."); };
  const remove = (index: number) => { const target = rows[index]; if (!target || !window.confirm(`Excluir a movimentação ${target.id}?`)) return; setData({ ...data, movements: data.movements.filter((m) => m !== target), auditEvents: [auditEvent("Movimentações", "Exclusão", target.id), ...data.auditEvents] }); showToast("Movimentação removida."); };
  return <div className="page-content"><PageHeader title="Movimentações de Estoque" description="Registre entradas, saídas, ajustes e transferências entre setores"><Button icon={Plus} onClick={() => setModal(true)}>Nova Movimentação</Button></PageHeader><div className="toolbar"><div className="search-box"><Search size={16} /><input placeholder="Buscar item, tipo ou documento..." value={query} onChange={(e) => setQuery(e.target.value)} /></div><span className="record-count">{rows.length} registros</span></div><div className="panel table-panel"><Table columns={["ID", "Tipo", "Item", "Quantidade", "Origem", "Destino", "Data"]} rows={rows.map((m) => [<span className="mono">{m.id}</span>, <Pill tone={m.type === "Entrada" ? "success" : m.type === "Saída" ? "danger" : "info"}>{m.type}</Pill>, m.item, `${m.quantity} ${m.unit}`.trim(), m.origin || "—", m.destination || "—", m.date || "—"])} onDelete={remove} empty="Nenhuma movimentação registrada." /></div>{modal && <Modal title="Nova Movimentação" onClose={() => setModal(false)} wide><form className="modal-form" onSubmit={save}><div className="form-grid"><Field label="Tipo *"><SelectInput value={form.type} onChange={(v) => setForm({ ...form, type: v })}><option>Entrada</option><option>Saída</option><option>Transferência</option><option>Ajuste</option></SelectInput></Field><Field label="Item *"><TextInput value={form.item} onChange={(v) => setForm({ ...form, item: v })} placeholder="Informe o item cadastrado" /></Field><Field label="Quantidade *"><TextInput value={form.quantity} onChange={(v) => setForm({ ...form, quantity: v })} type="number" placeholder="0" /></Field><Field label="Unidade"><TextInput value={form.unit} onChange={(v) => setForm({ ...form, unit: v })} placeholder="kg, un, L" /></Field><Field label="Origem"><TextInput value={form.origin} onChange={(v) => setForm({ ...form, origin: v })} /></Field><Field label="Destino"><TextInput value={form.destination} onChange={(v) => setForm({ ...form, destination: v })} /></Field><Field label="Data"><TextInput value={form.date} onChange={(v) => setForm({ ...form, date: v })} type="date" /></Field></div><Field label="Observação"><textarea className="input textarea" value={form.note} onChange={(e) => setForm({ ...form, note: e.target.value })} /></Field><div className="modal-actions"><Button variant="outline" onClick={() => setModal(false)}>Cancelar</Button><Button type="submit" icon={Check}>Registrar</Button></div></form></Modal>}</div>;
}

function QualityPage({ data, setData, category }: { data: typeof initialData; setData: (value: typeof initialData) => void; category: QualityRecord["category"] }) {
  const [modal, setModal] = useState(false); const [query, setQuery] = useState(""); const [form, setForm] = useState<QualityRecord>({ id: "", category, subject: "", status: category === "Checklist" ? "Pendente" : "Aberta", responsible: "", date: "", notes: "" }); const { showToast } = useToast(); const rows = useMemo(() => data.qualityRecords.filter((q) => q.category === category && Object.values(q).join(" ").toLowerCase().includes(query.toLowerCase())), [data.qualityRecords, category, query]);
  const save = (e: FormEvent) => { e.preventDefault(); if (!form.subject.trim()) { showToast("Informe o assunto do registro de qualidade."); return; } const next = { ...form, id: `${category === "Checklist" ? "CHK" : "NC"}-${Date.now()}`, date: form.date || new Date().toISOString().slice(0, 10) }; setData({ ...data, qualityRecords: [next, ...data.qualityRecords], auditEvents: [auditEvent("Qualidade", "Criação", `${next.category} · ${next.subject}`), ...data.auditEvents] }); setModal(false); setForm({ id: "", category, subject: "", status: category === "Checklist" ? "Pendente" : "Aberta", responsible: "", date: "", notes: "" }); showToast(category === "Checklist" ? "Checklist criado." : "Não conformidade registrada."); };
  const remove = (index: number) => { const target = rows[index]; if (!target || !window.confirm(`Excluir ${target.id}?`)) return; setData({ ...data, qualityRecords: data.qualityRecords.filter((q) => q !== target), auditEvents: [auditEvent("Qualidade", "Exclusão", target.id), ...data.auditEvents] }); showToast("Registro removido."); };
  const isChecklist = category === "Checklist";
  return <div className="page-content"><PageHeader title={isChecklist ? "Checklists de Qualidade" : "Não Conformidades"} description={isChecklist ? "Inspeções e verificações de qualidade" : "Registre, trate e acompanhe não conformidades"}><Button icon={Plus} onClick={() => setModal(true)}>{isChecklist ? "Novo Checklist" : "Nova Não Conformidade"}</Button></PageHeader><div className="toolbar"><div className="search-box"><Search size={16} /><input placeholder="Buscar registro..." value={query} onChange={(e) => setQuery(e.target.value)} /></div><span className="record-count">{rows.length} registros</span></div><div className="panel table-panel"><Table columns={["ID", "Assunto", "Responsável", "Data", "Status"]} rows={rows.map((q) => [<span className="mono">{q.id}</span>, q.subject, q.responsible || "—", q.date || "—", <Pill tone={q.status === "Concluído" || q.status === "Resolvida" ? "success" : q.status === "Aberta" ? "danger" : "warning"}>{q.status}</Pill>])} onDelete={remove} empty={isChecklist ? "Nenhum checklist cadastrado." : "Nenhuma não conformidade registrada."} /></div>{modal && <Modal title={isChecklist ? "Novo Checklist" : "Nova Não Conformidade"} onClose={() => setModal(false)}><form className="modal-form"><Field label="Assunto *"><TextInput value={form.subject} onChange={(v) => setForm({ ...form, subject: v })} placeholder={isChecklist ? "Nome da inspeção" : "Descrição da ocorrência"} /></Field><div className="form-grid"><Field label="Responsável"><TextInput value={form.responsible} onChange={(v) => setForm({ ...form, responsible: v })} /></Field><Field label="Data"><TextInput value={form.date} onChange={(v) => setForm({ ...form, date: v })} type="date" /></Field><Field label="Status"><SelectInput value={form.status} onChange={(v) => setForm({ ...form, status: v })}>{isChecklist ? <><option>Pendente</option><option>Em andamento</option><option>Concluído</option></> : <><option>Aberta</option><option>Em tratamento</option><option>Resolvida</option></>}</SelectInput></Field></div><Field label="Observações"><textarea className="input textarea" value={form.notes} onChange={(e) => setForm({ ...form, notes: e.target.value })} /></Field><div className="modal-actions"><Button variant="outline" onClick={() => setModal(false)}>Cancelar</Button><Button type="submit" icon={Check} onClick={(e) => { e.preventDefault(); save(e); }}>Salvar</Button></div></form></Modal>}</div>;
}

function MaintenancePage({ data, setData }: { data: typeof initialData; setData: (value: typeof initialData) => void }) {
  const [modal, setModal] = useState(false); const [query, setQuery] = useState(""); const [form, setForm] = useState<MaintenanceOrder>({ id: "", asset: "", type: "Preventiva", priority: "Normal", status: "Aberta", date: "", description: "" }); const { showToast } = useToast(); const rows = useMemo(() => data.maintenanceOrders.filter((m) => Object.values(m).join(" ").toLowerCase().includes(query.toLowerCase())), [data.maintenanceOrders, query]);
  const save = (e: FormEvent) => { e.preventDefault(); if (!form.asset.trim()) { showToast("Informe o equipamento da ordem de manutenção."); return; } const next = { ...form, id: `OM-${Date.now()}`, date: form.date || new Date().toISOString().slice(0, 10) }; setData({ ...data, maintenanceOrders: [next, ...data.maintenanceOrders], auditEvents: [auditEvent("Manutenção", "Criação", `${next.id} · ${next.asset}`), ...data.auditEvents] }); setModal(false); setForm({ id: "", asset: "", type: "Preventiva", priority: "Normal", status: "Aberta", date: "", description: "" }); showToast("Ordem de manutenção criada."); };
  const remove = (index: number) => { const target = rows[index]; if (!target || !window.confirm(`Excluir a ordem ${target.id}?`)) return; setData({ ...data, maintenanceOrders: data.maintenanceOrders.filter((m) => m !== target), auditEvents: [auditEvent("Manutenção", "Exclusão", target.id), ...data.auditEvents] }); showToast("Ordem removida."); };
  return <div className="page-content"><PageHeader title="Manutenção" description="Ordens de manutenção, prioridades e disponibilidade de máquinas"><Button icon={Plus} onClick={() => setModal(true)}>Nova Ordem</Button></PageHeader><div className="toolbar"><div className="search-box"><Search size={16} /><input placeholder="Buscar equipamento ou ordem..." value={query} onChange={(e) => setQuery(e.target.value)} /></div><span className="record-count">{rows.length} ordens</span></div><div className="panel table-panel"><Table columns={["ID", "Equipamento", "Tipo", "Prioridade", "Data", "Status"]} rows={rows.map((m) => [<span className="mono">{m.id}</span>, m.asset, m.type, <Pill tone={m.priority === "Urgente" ? "danger" : m.priority === "Alta" ? "warning" : "neutral"}>{m.priority}</Pill>, m.date || "—", <Pill tone={m.status === "Concluída" ? "success" : m.status === "Em execução" ? "info" : "warning"}>{m.status}</Pill>])} onDelete={remove} empty="Nenhuma ordem de manutenção cadastrada." /></div>{modal && <Modal title="Nova Ordem de Manutenção" onClose={() => setModal(false)}><form className="modal-form" onSubmit={save}><Field label="Equipamento *"><TextInput value={form.asset} onChange={(v) => setForm({ ...form, asset: v })} placeholder="Máquina ou ativo" /></Field><div className="form-grid"><Field label="Tipo"><SelectInput value={form.type} onChange={(v) => setForm({ ...form, type: v })}><option>Preventiva</option><option>Corretiva</option><option>Inspeção</option></SelectInput></Field><Field label="Prioridade"><SelectInput value={form.priority} onChange={(v) => setForm({ ...form, priority: v })}><option>Baixa</option><option>Normal</option><option>Alta</option><option>Urgente</option></SelectInput></Field><Field label="Status"><SelectInput value={form.status} onChange={(v) => setForm({ ...form, status: v })}><option>Aberta</option><option>Em execução</option><option>Concluída</option><option>Cancelada</option></SelectInput></Field><Field label="Data"><TextInput value={form.date} onChange={(v) => setForm({ ...form, date: v })} type="date" /></Field></div><Field label="Descrição"><textarea className="input textarea" value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })} /></Field><div className="modal-actions"><Button variant="outline" onClick={() => setModal(false)}>Cancelar</Button><Button type="submit" icon={Check}>Salvar ordem</Button></div></form></Modal>}</div>;
}

function AuditPage({ data }: { data: typeof initialData }) {
  const [query, setQuery] = useState(""); const rows = useMemo(() => data.auditEvents.filter((event) => Object.values(event).join(" ").toLowerCase().includes(query.toLowerCase())), [data.auditEvents, query]);
  return <div className="page-content"><PageHeader title="Auditoria" description="Histórico local de alterações realizadas no sistema"><div className="audit-count"><ShieldCheck size={16} />{rows.length} eventos</div></PageHeader><div className="toolbar"><div className="search-box"><Search size={16} /><input placeholder="Buscar módulo, usuário ou ação..." value={query} onChange={(e) => setQuery(e.target.value)} /></div></div><div className="panel table-panel"><Table columns={["Data", "Usuário", "Módulo", "Ação", "Detalhe"]} rows={rows.map((event) => [event.date, <span className="mono">{event.user}</span>, event.module, <Pill tone={event.action === "Exclusão" ? "danger" : event.action === "Criação" ? "success" : "info"}>{event.action}</Pill>, event.detail])} empty="Nenhum evento de auditoria registrado." /></div></div>;
}
'''
marker = '\nfunction RecipesPage'
if marker not in text: raise SystemExit('recipes marker not found')
text = text.replace(marker, '\n' + modules + marker, 1)
path.write_text(text)
print('pending modules added')
